insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V2A','Follow-up to v2 variant A (4 working days later)','Hi {first_name}, just checking this didn''t get buried. 15 minutes is plenty, and a one-line reply naming your most annoying bit of paperwork helps too.','neutral','trades','active','v2') on conflict (kind, code) do nothing;
insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V2B','Follow-up to v2 variant B','Hi {first_name}, one nudge on this. If you tell me how most of your new jobs come in, I''ll tell you plainly whether it''s something I can help with.','neutral','trades','active','v2') on conflict (kind, code) do nothing;
