insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V1-1','Follow-up to v1 draft 1','Hi {first_name}, just checking this didn''t get buried. Happy to come by at a quiet hour any afternoon next week; 15 minutes is plenty.','neutral','all','active','v1') on conflict (kind, code) do nothing;
insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V1-2','Follow-up to v1 draft 2','Hi {first_name}, a quick nudge on this. If you tell me the one task you''d most like to never do again, I''ll tell you straight whether we can automate it.','neutral','ai_keen','active','v1') on conflict (kind, code) do nothing;
insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V1-3','Follow-up to v1 draft 3','Hi {first_name}, no pressure on this. Even a one-line reply naming the task you hate most would help us, and we''ll tell you honestly if it''s fixable.','homely','shops','active','v1') on conflict (kind, code) do nothing;
insert into variants (kind, code, label, text, tone, audience, status, source) values ('follow_up','V1-4','Follow-up to v1 draft 4','Hi {first_name}, following up in case this landed at a busy moment. If late invoices or sorting enquiries isn''t a pain for you, tell me what is and I''ll see if we can help.','neutral','trades','active','v1') on conflict (kind, code) do nothing;
